CREATE FUNCTION public.work_access_internal(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_paid_bell(_user) OR EXISTS(SELECT 1 FROM public.membership_access WHERE user_id=_user AND feature_scope='work' AND revoked_at IS NULL AND starts_at<=now() AND ends_at>now()); $$;
REVOKE ALL ON FUNCTION public.work_access_internal(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.work_access_internal(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.has_work_membership(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (auth.uid()=_user OR auth.role()='service_role') AND public.work_access_internal(_user); $$;
DO $$ DECLARE f record; def text; BEGIN FOR f IN SELECT oid FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('match_post','guard_new_match_notifications','apply_service_priority','list_service_priority','can_notify','guard_prime99_notice','paid_alert_ready') LOOP def:=replace(pg_get_functiondef(f.oid),'public.has_paid_bell(','public.work_access_internal('); EXECUTE def; END LOOP; END $$;
CREATE FUNCTION public.route_endpoints_match(_a float8,_b float8,_c float8,_d float8,_e float8,_f float8,_g float8,_h float8) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT public.straight_line_km(_a,_b,_c,_d)>0 AND ((public.straight_line_km(_a,_b,_e,_f)<=public.straight_line_km(_a,_b,_c,_d)*0.20 AND public.straight_line_km(_c,_d,_g,_h)<=public.straight_line_km(_a,_b,_c,_d)*0.20) OR (public.straight_line_km(_a,_b,_g,_h)<=public.straight_line_km(_a,_b,_c,_d)*0.20 AND public.straight_line_km(_c,_d,_e,_f)<=public.straight_line_km(_a,_b,_c,_d)*0.20)); $$;
REVOKE ALL ON FUNCTION public.route_endpoints_match(float8,float8,float8,float8,float8,float8,float8,float8) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.route_endpoints_match(float8,float8,float8,float8,float8,float8,float8,float8) TO service_role;
CREATE OR REPLACE FUNCTION public.bell_route_within_radius(_post uuid,_demand uuid,_actor uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v record; d public.vehicle_bell_demands; typ text; BEGIN IF _actor IS NULL OR NOT public.profile_ready_for_actions(_actor) THEN RETURN false; END IF; IF _post IS NOT NULL THEN SELECT g.*,p.vehicle_type INTO v FROM public.vehicle_post_points g JOIN public.posts p ON p.id=g.post_id WHERE p.id=_post; ELSE SELECT * INTO d FROM public.vehicle_bell_demands WHERE id=_demand; IF d.post_id IS NOT NULL THEN SELECT g.*,p.vehicle_type INTO v FROM public.vehicle_post_points g JOIN public.posts p ON p.id=g.post_id WHERE p.id=d.post_id; ELSE SELECT g.*,r.vehicle_type INTO v FROM public.vehicle_route_points g JOIN public.vehicle_route_preferences r ON r.id=g.route_id AND r.user_id=g.user_id WHERE r.user_id=d.user_id AND r.enabled AND lower(trim(r.from_place))=lower(trim(d.from_place)) AND lower(trim(r.to_place))=lower(trim(d.to_place)) AND lower(trim(r.vehicle_type))=lower(trim(d.vehicle_type)) LIMIT 1; END IF; END IF; IF NOT FOUND THEN RETURN false; END IF; typ:=lower(trim(v.vehicle_type)); IF coalesce(typ,'')='' THEN RETURN false; END IF; RETURN EXISTS(SELECT 1 FROM public.vehicle_route_points g JOIN public.vehicle_route_preferences r ON r.id=g.route_id AND r.user_id=g.user_id JOIN public.account_programs a ON a.user_id=r.user_id WHERE r.user_id=_actor AND r.enabled AND a.member_kind IN('owner','business') AND lower(trim(r.vehicle_type))=typ AND public.route_endpoints_match(v.from_lat,v.from_lng,v.to_lat,v.to_lng,g.from_lat,g.from_lng,g.to_lat,g.to_lng)); END $$;
CREATE OR REPLACE FUNCTION public.vehicle_alert_context(_user uuid,_target uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id FROM public.posts p WHERE p.id=_target AND p.module='vehicle' AND public.post_listing_visible(p) AND public.has_paid_bell(_user) AND public.bell_route_within_radius(p.id,NULL,_user); $$;
CREATE FUNCTION public.enqueue_saved_vehicle_routes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; BEGIN IF TG_TABLE_NAME='vehicle_post_points' THEN pid:=NEW.post_id; INSERT INTO public.approximate_route_alerts(user_id,route_id,post_id) SELECT DISTINCT r.user_id,r.id,pid FROM public.vehicle_route_preferences r JOIN public.vehicle_route_points g ON g.route_id=r.id WHERE r.enabled AND r.user_id<>NEW.user_id AND public.bell_route_within_radius(pid,NULL,r.user_id) ON CONFLICT DO NOTHING; ELSE INSERT INTO public.approximate_route_alerts(user_id,route_id,post_id) SELECT NEW.user_id,NEW.route_id,p.id FROM public.posts p JOIN public.vehicle_post_points g ON g.post_id=p.id WHERE p.user_id<>NEW.user_id AND public.post_listing_visible(p) AND public.bell_route_within_radius(p.id,NULL,NEW.user_id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.enqueue_saved_vehicle_routes() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.enqueue_saved_vehicle_routes() TO service_role;
CREATE TRIGGER saved_vehicle_post_radius AFTER INSERT OR UPDATE ON public.vehicle_post_points FOR EACH ROW EXECUTE FUNCTION public.enqueue_saved_vehicle_routes();
CREATE TRIGGER saved_vehicle_preference_radius AFTER INSERT OR UPDATE ON public.vehicle_route_points FOR EACH ROW EXECUTE FUNCTION public.enqueue_saved_vehicle_routes();
CREATE OR REPLACE FUNCTION public.notify_exact_saved_return_route() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.module='vehicle' AND public.post_listing_visible(NEW) THEN INSERT INTO public.approximate_route_alerts(user_id,route_id,post_id) SELECT DISTINCT r.user_id,r.id,NEW.id FROM public.vehicle_route_preferences r WHERE r.enabled AND r.user_id<>NEW.user_id AND public.bell_route_within_radius(NEW.id,NULL,r.user_id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='dispatch_approximate_route_alerts'; def:=regexp_replace(def,'IF g.route_id IS NULL OR v.post_id IS NULL OR .*? THEN UPDATE public.approximate_route_alerts','IF g.route_id IS NULL OR v.post_id IS NULL OR NOT public.bell_route_within_radius(q.post_id,NULL,q.user_id) THEN UPDATE public.approximate_route_alerts','n'); def:=replace(def,'INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(q.user_id,own_post,CASE WHEN own_post=p.id THEN NULL ELSE p.id END,','PERFORM set_config(''app.bell_notice'',''owner'',true); INSERT INTO public.notifications(user_id,post_id,matched_post_id,message) VALUES(q.user_id,own_post,CASE WHEN own_post=p.id THEN NULL ELSE p.id END,'); EXECUTE def; END $$;
CREATE FUNCTION public.strict_vehicle_notice_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; BEGIN SELECT id INTO pid FROM public.posts WHERE id IN(NEW.post_id,NEW.matched_post_id) AND module='vehicle' LIMIT 1; IF NEW.vehicle_bell OR pid IS NOT NULL THEN IF NOT public.has_paid_bell(NEW.user_id) OR NOT public.profile_ready_for_actions(NEW.user_id) THEN RETURN NULL; END IF; IF NEW.vehicle_bell THEN IF NOT public.bell_route_within_radius(NEW.post_id,NEW.bell_demand,NEW.bell_actor) THEN RETURN NULL; END IF; ELSE IF NOT public.bell_route_within_radius(pid,NULL,NEW.user_id) THEN RETURN NULL; END IF; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.strict_vehicle_notice_guard() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.strict_vehicle_notice_guard() TO service_role;
CREATE TRIGGER b_strict_vehicle_notice BEFORE INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.strict_vehicle_notice_guard();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='notification_delivery_allowed'; def:=replace(def,'(NOT n.vehicle_bell OR public.bell_route_within_radius(n.post_id,n.bell_demand,n.bell_actor))','(NOT n.vehicle_bell OR (public.has_paid_bell(_user) AND public.bell_route_within_radius(n.post_id,n.bell_demand,n.bell_actor))) AND (NOT EXISTS(SELECT 1 FROM public.posts p WHERE p.id IN(n.post_id,n.matched_post_id) AND p.module=''vehicle'') OR (public.has_paid_bell(_user) AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id IN(n.post_id,n.matched_post_id) AND p.module=''vehicle'' AND public.bell_route_within_radius(p.id,NULL,_user))))'); EXECUTE def; END $$;